    !r ||
    !p ||
    p.dead ||
    !plan.maker ||
    s.battle ||
    s.event ||
    Object.entries(plan.cost).some(([k, v]) => s.inventory[k] < v) ||
    (id === "blade" && p.weapon >= 4) ||
    (id === "armor" && p.armor >= 3)
