  steppedOval(c, 4, 28, 20, 5, "#63724b88");
  pixel(c, 8, 23 + step, 4, 8 - step, "#3e4135");
  pixel(c, 15, 23 - step, 4, 8 + step, "#3e4135");
  pixel(c, 7, 29 + step, 6, 2, "#655440");
  pixel(c, 15, 29 - step, 6, 2, "#655440");
