  pixel(c, 10, 15, 7, 8, coat);
  pixel(c, 9, 23, 10, 2, "#72563c");
  pixel(c, 13, 23, 2, 2, "#d6b574");
  pixel(c, 5, 15, 3, 6, coat);
  pixel(c, 20, 15, 3, 6, coat);
